 {"author": "Pinchas Lapide", "title": "The Resurrection of Jesus: A Jewish Perspective", "year": 1983, "level": "deeper", "why": "An Orthodox Jewish scholar who took the evidence seriously (German 1977)."},
 {"author": "Mona Siddiqui", "title": "Christians, Muslims, and Jesus", "year": 2013, "level": "deeper", "why": "A Muslim scholar on how the two faiths see Jesus and the cross."},
